#include "fullstack_mock_app_backend.h"
#include <cassert>
#include <thread>
int main(){FS_Error e=FS_ERROR_INIT;assert(fs_app_register_mock_backend(&e)==FS_RESULT_OK);assert(fs_app_backend_count()>=1);FS_AppDesc d=FS_APP_DESC_INIT;d.backend_name="mock";d.create_default_window=true;d.default_window.width=320;d.default_window.height=240;FS_App*a=nullptr;assert(fs_app_create(&d,&a,&e)==FS_RESULT_OK);assert(fs_app_backend_unregister("mock",&e)==FS_RESULT_INVALID_STATE);assert(fs_app_window_count(a)==1);assert(fs_app_thread_roles(a)->app_thread==fs_app_thread_roles(a)->backend_thread);FS_AppWindow*w=fs_app_window_at(a,0);assert(fs_app_window_metrics(w)->logical_width==320);assert(fs_app_begin_frame(a,&e)==FS_RESULT_OK);assert(fs_app_begin_frame(a,&e)==FS_RESULT_INVALID_STATE);FS_AppEvent key=FS_APP_EVENT_INIT;key.type=FS_APP_EVENT_KEY;key.window_id=fs_app_window_id(w);key.data.key.key=9;key.data.key.action=FS_APP_KEY_PRESS;assert(fs_mock_backend_inject_event(a,&key,&e)==FS_RESULT_OK);assert(fs_app_poll_event(a,&key,&e)==FS_RESULT_INVALID_STATE);assert(fs_app_pump_events(a,FS_APP_PUMP_POLL,0,&e)==FS_RESULT_OK);assert(fs_app_pump_events(a,FS_APP_PUMP_POLL,0,&e)==FS_RESULT_INVALID_STATE);FS_AppEvent out=FS_APP_EVENT_INIT;assert(fs_app_poll_event(a,&out,&e)==FS_RESULT_OK);assert(fs_app_window_input(w)->keys_pressed[9]);assert(fs_app_poll_event(a,&out,&e)==FS_RESULT_SKIP);assert(fs_app_end_frame(a,&e)==FS_RESULT_OK);FS_AppWindowMetrics m=*fs_app_window_metrics(w);m.logical_width=400;m.framebuffer_width=800;m.scale_x=2;assert(fs_mock_window_set_metrics(w,&m,&e)==FS_RESULT_OK);assert(fs_app_begin_frame(a,&e)==FS_RESULT_OK);assert(fs_app_pump_events(a,FS_APP_PUMP_POLL,0,&e)==FS_RESULT_OK);assert(fs_app_poll_event(a,&out,&e)==FS_RESULT_OK);assert(fs_app_window_metrics(w)->framebuffer_width==800);assert(fs_app_end_frame(a,&e)==FS_RESULT_OK);FS_Result other=FS_RESULT_OK;std::thread t([&](){other=fs_app_begin_frame(a,&e);});t.join();assert(other==FS_RESULT_WRONG_THREAD);assert(fs_app_begin_destroy(a,&e)==FS_RESULT_OK);fs_app_release(a);assert(fs_app_backend_unregister("mock",&e)==FS_RESULT_OK);return 0;}
